CÓDIGO:
package com.sorteio;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.view.View;
import android.widget.TextView;

import java.util.Random;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
    }

    TextView resultado;                                            //Criando a variaveis da classe TextView
    TextView menor;
    TextView maior;

    public void sortear (View v) {
        resultado = findViewById(R.id.textView3);                 //Atrelando a variavel TextWiew ao ID da caixa de diálogo do activity_main
        menor = findViewById(R.id.editText);
        maior = findViewById(R.id.editText3);

        int menorNumero = lerNumeroInteiro(menor);
        int maiorNumero = lerNumeroInteiro(maior);

        int aleatorio = funcaoSortear (menorNumero, maiorNumero);

        resultado.setText("Número: " + aleatorio);
    }

    public int funcaoSortear(int min, int max) {
            int result = max - min + 1;
            result = new Random().nextInt(result);
            result = min + result;
            return result;
    }

    public int lerNumeroInteiro (TextView endereco) {
        int valorLido = Integer.parseInt(endereco.getText().toString());     //colocar na variavel inteira, um texto do obtido do ID textWieW, to string indica o formato a ser passado
        return valorLido;
    }
}

